classdef Circ
    properties (Constant)
        UnitArea = pi
    end
    properties
        r = 1
    end
    properties (Dependent)
        area
    end
    methods
        function a = get.area(obj)
            a = pi * obj.r^2;
        end
        function obj = set.area(obj, a)
            obj.r = sqrt(a / pi);
        end
        function obj = set.r(obj, v)
            if v < 0, error('Circ:neg', 'negative'); end
            obj.r = v;
        end
    end
    methods (Static)
        function c = unit()
            c = Circ();
        end
        function v = twice(x)
            v = 2 * x;
        end
    end
end

