classdef V2
    properties
        a = 0
        b = 0
    end
    methods
        function o = V2(a, b)
            if nargin, o.a = a; o.b = b; end
        end
        function r = plus(p, q)
            r = V2(p.a + q.a, p.b + q.b);
        end
        function r = minus(p, q)
            r = V2(p.a - q.a, p.b - q.b);
        end
        function r = mtimes(p, k)
            if isa(p, 'double'), t = p; p = k; k = t; end
            r = V2(p.a * k, p.b * k);
        end
        function r = eq(p, q)
            r = p.a == q.a && p.b == q.b;
        end
        function r = uminus(p)
            r = V2(-p.a, -p.b);
        end
        function r = lt(p, q)
            r = norm([p.a p.b]) < norm([q.a q.b]);
        end
        function disp(p)
            fprintf('V2(%d,%d)\n', p.a, p.b);
        end
    end
end

