classdef Stack < handle
    properties (SetAccess = private)
        items = {}
    end
    properties (Dependent)
        Count
    end
    methods
        function push(obj, x)
            obj.items{end+1} = x;
        end
        function x = pop(obj)
            if isempty(obj.items), error('Stack:empty', 'stack is empty'); end
            x = obj.items{end}; obj.items(end) = [];
        end
        function n = get.Count(obj)
            n = numel(obj.items);
        end
    end
end

classdef Temp
    properties
        C = 0
    end
    properties (Dependent)
        F
    end
    methods
        function obj = Temp(c)
            if nargin, obj.C = c; end
        end
        function f = get.F(obj)
            f = obj.C * 9 / 5 + 32;
        end
        function obj = set.F(obj, f)
            obj.C = (f - 32) * 5 / 9;
        end
        function obj = warm(obj, d)
            obj.C = obj.C + d;
        end
        function r = plus(a, b)
            r = Temp(a.C + b.C);
        end
        function tf = lt(a, b)
            tf = a.C < b.C;
        end
        function s = char(obj)
            s = sprintf('%.1f C', obj.C);
        end
    end
    methods (Static)
        function t = boiling()
            t = Temp(100);
        end
    end
end

