    methods
        function obj = BigTruck()
            obj@Truck(99);
        end
        function n = horn(~)
            n = 'HONK';
        end
    end
end

classdef Truck < Vehicle
    properties
        load = 0
    end
    methods
        function obj = Truck(l)
            obj@Vehicle(6);
            obj.load = l;
            obj.log{end+1} = 'Truck';
        end
        function d = describe(obj)
            d = [describe@Vehicle(obj) sprintf(', load %d', obj.load)];
        end
        function v = reveal(obj)
            v = obj.secret() + 1;
        end
    end
end

classdef Vehicle < handle
    properties
        wheels = 4
        log = {}
    end
    properties (Constant)
        Kind = 'vehicle'
    end
    methods
        function obj = Vehicle(w)
            if nargin, obj.wheels = w; end
            obj.log{end+1} = 'Vehicle';
        end
        function d = describe(obj)
            d = sprintf('%d wheels', obj.wheels);
        end
        function n = horn(~)
            n = 'beep';
        end
    end
    methods (Access = protected)
        function v = secret(~)
            v = 42;
        end
    end
end

